package org.beckenburg;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

/** Immutable, bounded and atomically saved map sound layout. */
public record SoundDocument(String level,List<SoundVolume> volumes) {
    public SoundDocument{if(level==null||!level.matches("[A-Za-z0-9_-]{1,80}")||volumes==null||volumes.size()>64)throw new IllegalArgumentException("Sound document limits");volumes=List.copyOf(volumes);var ids=new HashSet<String>();for(var v:volumes)if(!ids.add(v.id()))throw new IllegalArgumentException("Duplicate sound ID");}
    public String encode(){var b=new StringBuilder("sounds=1\nlevel="+level+"\n");for(var v:volumes)b.append(String.join("|",v.id(),v.kind().name(),v.shape().name(),v.source().name(),""+v.x(),""+v.y(),""+v.z(),""+v.width(),""+v.height(),""+v.depth(),""+v.falloff(),""+v.gain(),""+v.pitch(),""+v.fade(),""+v.duration(),""+v.enabled(),""+v.loop(),""+v.requiresPower())).append('\n');return b.toString();}
    public String revision(){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(encode().getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new AssertionError(e);}}
    private static boolean bool(String s){if(!s.equals("true")&&!s.equals("false"))throw new IllegalArgumentException("Invalid sound flag");return Boolean.parseBoolean(s);}
    public static SoundDocument read(InputStream input)throws IOException{if(input==null)throw new IOException("Missing sound document");byte[] bytes;try(input){bytes=input.readNBytes(100001);}if(bytes.length>100000)throw new IOException("Sound document exceeds100KB");var lines=new String(bytes,StandardCharsets.UTF_8).lines().toList();try{if(lines.size()<2||!lines.get(0).equals("sounds=1")||!lines.get(1).startsWith("level="))throw new IllegalArgumentException("Sound document header");var items=new ArrayList<SoundVolume>();for(String line:lines.subList(2,lines.size())){String[] p=line.split("\\|",-1);if(p.length!=18)throw new IllegalArgumentException("Sound field count");items.add(new SoundVolume(p[0],SoundVolume.Kind.valueOf(p[1]),SoundVolume.Shape.valueOf(p[2]),SoundVolume.Source.valueOf(p[3]),Double.parseDouble(p[4]),Double.parseDouble(p[5]),Double.parseDouble(p[6]),Double.parseDouble(p[7]),Double.parseDouble(p[8]),Double.parseDouble(p[9]),Double.parseDouble(p[10]),Double.parseDouble(p[11]),Double.parseDouble(p[12]),Double.parseDouble(p[13]),Double.parseDouble(p[14]),bool(p[15]),bool(p[16]),bool(p[17])));}return new SoundDocument(lines.get(1).substring(6),items);}catch(IllegalArgumentException e){throw new IOException("Invalid sound layout: "+e.getMessage(),e);}}
    public void save(Path path)throws IOException{Path target=path.toAbsolutePath().normalize();Files.createDirectories(target.getParent());Path temporary=Files.createTempFile(target.getParent(),"sound-",".tmp");try{Files.writeString(temporary,encode(),StandardCharsets.UTF_8);try{Files.move(temporary,target,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temporary,target,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temporary);}}
    public static Path path(String level){if(!level.matches("[A-Za-z0-9_-]{1,80}"))throw new IllegalArgumentException("Sound level ID");String root=System.getProperty("beckenburg.sound.documents","");return(root.isBlank()?Path.of(System.getProperty("user.home"),".beckenburg/editor/sounds"):Path.of(root)).resolve(level+".sounds");}
    public static SoundDocument load(String level){try{Path p=path(level);SoundDocument d;if(Files.exists(p))d=read(Files.newInputStream(p));else try(var in=SoundDocument.class.getResourceAsStream("/org/beckenburg/sounds/"+level+".sounds")){d=in==null?new SoundDocument(level,List.of()):read(in);}if(!d.level.equals(level))throw new IOException("Sound layout belongs to another map");return d;}catch(IOException e){throw new IllegalStateException(e.getMessage(),e);}}
}
